function formatToday(){return new Intl.DateTimeFormat("es-CL",{weekday:"long",day:"numeric",month:"long"}).format(new Date())}
function evaluationCourse(item){return courses.find(course=>course.id===item.subjectId)}
function evaluationStatus(item){if(item.status==="completed")return{label:"Realizada",tone:"available",days:null};const days=daysUntil(item.date);return{days,label:days===0?"Hoy":days===1?"Mañana":days<0?"Atrasada":`Faltan ${days} días`,tone:days<=2?"late":days<=7?"request":"available"}}
function assignmentCourse(item){return courses.find(course=>course.id===item.subjectId)}
function assignmentStatus(item){const days=daysUntil(item.dueDate);if(item.status==="completed")return{days,label:"Entregada",tone:"available",priority:"Baja",priorityTone:"available",due:"Entregada"};if(item.status==="overdue"||days<0)return{days,label:"Atrasada",tone:"late",priority:"Alta",priorityTone:"late",due:"Atrasada"};const priority=days<=2?"Alta":days<=7?"Media":"Baja",priorityTone=days<=2?"late":days<=7?"request":"available";return{days,label:"Pendiente",tone:"request",priority,priorityTone,due:days===0?"Entrega hoy":days===1?"Entrega mañana":`Faltan ${days} días`}}
function pendingAssignments(){return assignments.filter(item=>item.status!=="completed"&&daysUntil(item.dueDate)>=0)}
function addAssignmentReminder(id){const item=assignments.find(assignment=>assignment.id===id),course=assignmentCourse(item||{});if(!item||!course)return;const list=reminders(),exists=list.some(reminder=>reminder.assignmentId===id);if(!exists){list.push({assignmentId:id,title:`${item.title} · ${course.name}`,date:item.dueDate,type:"Entrega",when:"1 día antes",subjectId:course.id}) ;localStorage.setItem("uboReminders",JSON.stringify(list))}toast(exists?"Este recordatorio ya está agregado.":"Recordatorio agregado al calendario académico.")}
