function activeLibraryBooks(){return libraryBooks.map(book=>libraryBook(book.id))}
function libraryCalendarEntries(){return activeLibraryBooks().filter(book=>book.status==="borrowed"&&book.returnDate).map(book=>({id:book.id,key:`library:${book.id}`,source:"library",type:"Biblioteca",title:`Devolución biblioteca: ${book.title}`,date:book.returnDate,time:"Antes del cierre",room:"Biblioteca UBO",subject:"Biblioteca UBO",description:`Fecha límite de devolución para ${book.title}.`,libraryBookId:book.id}))}
function calendarEntries(){const regular=events.map(item=>({...item,key:`event:${item.id}`,source:"event"})),assessment=evaluations.map(item=>{const course=evaluationCourse(item);return{...item,key:`evaluation:${item.id}`,source:"evaluation",type:"Evaluación",subject:course?.name||"Ramo",professor:course?.teacher||"",description:`${item.title} · Ponderación ${item.percentage}%`}}),deliveries=assignments.map(item=>{const course=assignmentCourse(item),state=assignmentStatus(item);return{...item,key:`assignment:${item.id}`,source:"assignment",type:"Entrega",date:item.dueDate,time:item.dueTime,room:"Aula virtual",subject:course?.name||"Ramo",professor:course?.teacher||"",description:item.description,status:item.status,stateLabel:state.label}}),saved=reminders().map((item,index)=>({...item,key:`reminder:${item.evaluationId||item.assignmentId||item.campusEventId||item.libraryBookId||index}`,source:"reminder",type:"Recordatorio",eventType:item.type,subject:assignmentCourse(item)?.name||item.subject||"",subjectId:item.subjectId,description:`Recordatorio configurado: ${item.when}`,time:item.time||"Todo el día",room:item.room||"Agenda personal"}));return[...regular,...assessment,...deliveries,...campusCalendarEntries(),...libraryCalendarEntries(),...saved].sort((a,b)=>a.date.localeCompare(b.date)||String(a.time).localeCompare(String(b.time)))}
function notificationMeta(type){return({academic:{icon:"📚",label:"Académica",tone:"academic"},assignment:{icon:"📝",label:"Entrega",tone:"assignment"},evaluation:{icon:"🔴",label:"Evaluación",tone:"evaluation"},attendance:{icon:"⚠️",label:"Asistencia",tone:"attendance"},event:{icon:"🎓",label:"Evento UBO",tone:"event"},reminder:{icon:"🔔",label:"Recordatorio",tone:"reminder"}}[type]||{icon:"🔔",label:"Aviso",tone:"academic"})}
function notificationState(){const state=json("uboNotificationState",{});return state&&typeof state==="object"&&!Array.isArray(state)?state:{}}
function buildNotifications(){const generated=[],today=isoDate(),state=notificationState(),push=item=>generated.push({...item,date:item.date||today,read:Boolean(state[item.id]?.read)});evaluations.filter(item=>item.status!=="completed"&&daysUntil(item.date)>=0&&daysUntil(item.date)<=7).forEach(item=>{const course=evaluationCourse(item),status=evaluationStatus(item);push({id:`evaluation:${item.id}`,type:"evaluation",title:status.days===0?"Evaluación hoy":status.days===1?"Evaluación mañana":"Evaluación próxima",message:`${item.title} · ${course?.name||"Ramo"} · ${item.time} · ${item.room}`,date:item.date,priority:status.days<=1?"high":"medium",subjectId:item.subjectId,targetId:item.id})});assignments.filter(item=>item.status!=="completed"&&daysUntil(item.dueDate)>=0&&daysUntil(item.dueDate)<=7).forEach(item=>{const course=assignmentCourse(item),status=assignmentStatus(item);push({id:`assignment:${item.id}`,type:"assignment",title:"Entrega próxima",message:`${item.title} · ${course?.name||"Ramo"} · ${status.due} ${item.dueTime}`,date:item.dueDate,priority:status.days<=1?"high":"medium",subjectId:item.subjectId,targetId:item.id})});courses.filter(course=>Number(course.attendance)<80).forEach(course=>push({id:`attendance:${course.id}`,type:"attendance",title:"Alerta académica",message:`Tu asistencia en ${course.name} está en ${course.attendance}%. Procura llegar al mínimo requerido.`,date:today,priority:"high",subjectId:course.id,targetId:course.id}));schedule.filter(item=>item.day===todayKey()).forEach(item=>push({id:`class:${today}:${item.subjectId}:${item.time}`,type:"academic",title:"Clase programada hoy",message:`${item.subject} · ${item.time} · ${item.room}`,date:today,priority:"medium",subjectId:item.subjectId,targetId:item.subjectId}));events.filter(item=>item.type==="Evento UBO"&&daysUntil(item.date)>=0&&daysUntil(item.date)<=7).forEach(item=>push({id:`event:${item.id}`,type:"event",title:"Evento UBO próximo",message:`${item.title} · ${relativeEvent(item)} · ${item.time}`,date:item.date,priority:"low",calendarKey:`event:${item.id}`}));campusEvents.filter(item=>campusRegistered(item.id)&&daysUntil(item.date)>=0&&daysUntil(item.date)<=7).forEach(item=>push({id:`campus:${item.id}`,type:"event",title:"Evento UBO próximo",message:`${item.title} · ${formatDate(item.date)} · ${item.time}`,date:item.date,priority:daysUntil(item.date)<=2?"medium":"low",campusEventId:item.id}));activeLibraryBooks().filter(item=>item.status==="borrowed"&&item.returnDate&&daysUntil(item.returnDate)>=0&&daysUntil(item.returnDate)<=3).forEach(item=>push({id:`library:${item.id}`,type:"academic",title:"Biblioteca UBO",message:`Tu libro vence ${daysUntil(item.returnDate)===0?"hoy":daysUntil(item.returnDate)===1?"mañana":`en ${daysUntil(item.returnDate)} días`}: ${item.title}.`,date:item.returnDate,priority:daysUntil(item.returnDate)<=1?"high":"medium",libraryBookId:item.id}));reminders().filter(item=>item.date&&daysUntil(item.date)>=0&&daysUntil(item.date)<=7).forEach((item,index)=>push({id:`reminder:${item.evaluationId||item.assignmentId||item.campusEventId||item.libraryBookId||index}`,type:"reminder",title:"Recordatorio académico",message:`${item.title} · ${relativeEvent(item)}`,date:item.date,priority:daysUntil(item.date)<=1?"high":"medium",subjectId:item.subjectId,targetId:item.evaluationId||item.assignmentId||item.campusEventId||item.libraryBookId,reminderType:item.evaluationId?"evaluation":item.assignmentId?"assignment":item.campusEventId?"campus":item.libraryBookId?"library":"calendar"}));const priority={high:0,medium:1,low:2};generated.sort((a,b)=>priority[a.priority]-priority[b.priority]||a.date.localeCompare(b.date));notifications.splice(0,notifications.length,...generated);return notifications}
function markNotificationRead(id){const state=notificationState();state[id]={read:true};localStorage.setItem("uboNotificationState",JSON.stringify(state));renderHomeNotifications();renderNotifications();if(currentScreen==="notification-detail")notificationDetail(id)}
function notificationMatches(item,filter){return filter==="Todas"||filter==="Académicas"&&["academic","attendance","event","reminder"].includes(item.type)||filter==="Entregas"&&item.type==="assignment"||filter==="Evaluaciones"&&item.type==="evaluation"||filter==="Importantes"&&item.priority==="high"}
function renderHomeNotifications(){const list=buildNotifications(),unread=list.filter(item=>!item.read),items=(unread.length?unread:list).slice(0,3),count=unread.length;$("#notification-count").textContent=`${count} pendiente${count===1?"":"s"}`;$("#notification-dot").classList.toggle("hidden",count===0);$("#home-notifications").innerHTML=items.map(item=>{const meta=notificationMeta(item.type);return`<button class="home-notification-card ${item.priority} ${item.read?"read":""}" data-notification="${item.id}"><span>${meta.icon}</span><div><small>${meta.label} · ${relativeEvent(item)}</small><b>${item.title}</b><p>${item.message}</p></div><i>›</i></button>`}).join("")||"<p class='card-meta'>No tienes alertas importantes.</p>"}
function renderNotifications(filter=notificationFilter){notificationFilter=filter;const list=buildNotifications().filter(item=>notificationMatches(item,filter)),filters=["Todas","Académicas","Entregas","Evaluaciones","Importantes"];$("#notification-filters").innerHTML=filters.map(name=>`<button class="filter-btn ${name===filter?"active":""}" data-notification-filter="${name}">${name}</button>`).join("");$("#notification-list").innerHTML=list.map(item=>{const meta=notificationMeta(item.type),priority=item.priority==="high"?"Importante":item.priority==="medium"?"Próxima":"Informativa";return`<article class="notification-card ${meta.tone} ${item.priority} ${item.read?"read":""}"><div class="notification-card-top"><span>${meta.icon}</span><div><small>${meta.label} · ${priority}</small><h3>${item.title}</h3></div>${item.read?"<span class='notification-read'>Leída</span>":"<span class='notification-new'>Nueva</span>"}</div><p>${item.message}</p><div class="notification-actions"><button class="outline-btn" data-notification="${item.id}">Ver detalle</button>${item.read?"":`<button class="text-btn" data-notification-read="${item.id}">Marcar como leída</button>`}</div></article>`}).join("")||"<p class='card-meta'>No hay notificaciones en esta categoría.</p>"}
function notificationDetail(id){const item=buildNotifications().find(notification=>notification.id===id);if(!item)return;const meta=notificationMeta(item.type),course=courses.find(entry=>entry.id===item.subjectId),actions=item.type==="evaluation"?`<button class="primary-btn" data-notification-evaluation="${item.targetId}">Ver evaluación</button>`:item.type==="assignment"?`<button class="primary-btn" data-notification-assignment="${item.targetId}">Ver entrega</button>`:item.type==="event"&&item.campusEventId?`<button class="primary-btn" data-notification-campus="${item.campusEventId}">Ver evento</button>`:item.type==="event"?`<button class="primary-btn" data-calendar-event="${item.calendarKey}">Ver evento</button>`:item.libraryBookId?`<button class="primary-btn" data-notification-library="${item.libraryBookId}">Ver libro</button>`:item.reminderType==="evaluation"?`<button class="primary-btn" data-notification-evaluation="${item.targetId}">Ver evaluación</button>`:item.reminderType==="assignment"?`<button class="primary-btn" data-notification-assignment="${item.targetId}">Ver entrega</button>`:item.reminderType==="campus"?`<button class="primary-btn" data-notification-campus="${item.targetId}">Ver evento</button>`:item.reminderType==="library"?`<button class="primary-btn" data-notification-library="${item.targetId}">Ver libro</button>`:course?`<button class="primary-btn" data-notification-course="${course.id}">Ver ramo</button>`:"";$("#notification-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">${meta.icon} ${meta.label.toUpperCase()}</span><h2>${item.title}</h2><p>${course?.name||"Información académica"}</p><span class="badge ${item.priority==="high"?"late":item.priority==="medium"?"request":"available"}">${item.read?"Leída":item.priority==="high"?"Importante":"Nueva"}</span></div><section class="class-info-card"><div><span>Tipo</span><b>${meta.label}</b></div><div><span>Fecha</span><b>${formatDate(item.date)}</b></div><div><span>Estado</span><b>${item.read?"Leída":"No leída"}</b></div>${course?`<div><span>Ramo relacionado</span><b>${course.name}</b></div>`:""}</section><section class="card-section"><h3>Detalle</h3><article class="announcement-card"><p>${item.message}</p></article></section><div class="notification-detail-actions">${actions}${item.read?"":`<button class="outline-btn" data-notification-read="${item.id}">Marcar como leída</button>`}</div>`;showScreen("notification-detail")}
function renderDashboard(){const s=student(),average=(courses.reduce((sum,course)=>sum+course.grade,0)/courses.length).toFixed(1),attendance=Math.round(courses.reduce((sum,course)=>sum+course.attendance,0)/courses.length),academicState=courses.some(course=>course.state==="En alerta")?"Atención":s.status;$("#dashboard-name").textContent=`Hola, ${s.name.split(" ")[0]} 👋`;$("#dashboard-career").textContent=s.career;$("#dashboard-period").textContent=s.semester;$("#dashboard-status").textContent=s.status;$("#dashboard-average").textContent=average;$("#dashboard-attendance").textContent=`${attendance}%`;$("#dashboard-courses").textContent=courses.length;$("#dashboard-academic-state").textContent=academicState}
function renderHomeAttention(){const nextEvaluation=[...evaluations].filter(item=>item.status!=="completed"&&daysUntil(item.date)>=0).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time))[0],nextAssignment=[...pendingAssignments()].sort((a,b)=>a.dueDate.localeCompare(b.dueDate)||a.dueTime.localeCompare(b.dueTime))[0],notification=buildNotifications().find(item=>!item.read&&item.priority==="high"&&item.type!=="evaluation"&&item.type!=="assignment"),items=[notification&&{kind:"notification",id:notification.id,icon:notificationMeta(notification.type).icon,label:"Alta prioridad",title:notification.title,detail:notification.message},nextEvaluation&&{kind:"evaluation",id:nextEvaluation.id,icon:"🔴",label:`${relativeEvent({date:nextEvaluation.date})} · Evaluación`,title:nextEvaluation.title,detail:`${evaluationCourse(nextEvaluation)?.name||"Ramo"} · ${nextEvaluation.time}`},nextAssignment&&{kind:"assignment",id:nextAssignment.id,icon:"📝",label:`${assignmentStatus(nextAssignment).due} · Entrega`,title:nextAssignment.title,detail:`${assignmentCourse(nextAssignment)?.name||"Ramo"} · ${nextAssignment.dueTime}`}].filter(Boolean);$("#dashboard-attention").innerHTML=items.map(item=>`<button class="dashboard-attention-card ${item.kind}" data-${item.kind}="${item.id}"><span>${item.icon}</span><div><small>${item.label}</small><b>${item.title}</b><p>${item.detail}</p></div><i>›</i></button>`).join("")||"<p class='card-meta'>No tienes asuntos prioritarios por revisar.</p>"}
function renderToday(){const items=schedule.filter(item=>item.day===todayKey()),todayItems=calendarEntries().filter(item=>item.date===isoDate()&&item.status!=="completed"),currentTime=`${String(new Date().getHours()).padStart(2,"0")}:${String(new Date().getMinutes()).padStart(2,"0")}`,next=items.find(item=>item.time.split(" - ")[0]>=currentTime)||items[0];$("#today-date").textContent=`Hoy · ${formatToday()}`;$("#today-evaluations").innerHTML=todayItems.map(item=>{const meta=eventMeta(item.type),course=evaluationCourse(item);return`<article class="today-evaluation ${meta.tone}"><span>${meta.icon}</span><div><b>${item.type}: ${item.title}</b><p>${course?.name?`${course.name} · `:""}${item.time}${item.room?` · ${item.room}`:""}</p></div><button class="outline-btn" data-calendar-event="${item.key}">Ver detalle</button></article>`}).join("");$("#today-classes").innerHTML=items.length?items.map(item=>`<article class="today-class-card ${item===next?"next-class":""}"><div class="today-time">${item.time.split(" - ")[0]}<small>${item.time.split(" - ")[1]}</small></div><div><span class="today-subject-icon">📘</span><h4>${item.subject}</h4><p>${item.room} · ${item.professor}</p></div><button class="outline-btn" data-class="${item.subjectId}" data-class-day="${item.day}">Ver detalle</button></article>`).join(""):`<article class="today-empty"><span>◷</span><div><b>No tienes actividades académicas hoy.</b><p>Revisa tu calendario para conocer las próximas fechas importantes.</p></div></article>`}
function renderHomeEvents(){const regular=events.filter(item=>item.type==="Evento UBO"&&daysUntil(item.date)>=0).map(item=>({...item,key:`event:${item.id}`,kind:"calendar"})),campus=campusEvents.filter(item=>daysUntil(item.date)>=0).map(item=>({...item,room:item.location,kind:"campus"})),items=[...regular,...campus].sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)).slice(0,3);$("#upcoming-events").innerHTML=items.map(item=>`<button class="upcoming-event-card available" ${item.kind==="campus"?`data-campus-event="${item.id}"`:`data-calendar-event="${item.key}"`}><span>🎓</span><div><small>${relativeEvent(item)}</small><b>${item.title}</b><p>${formatDate(item.date)} · ${item.room}</p></div><i>›</i></button>`).join("")||"<p class='card-meta'>No tienes próximos eventos institucionales.</p>"}
function renderHomeDeliveries(){const items=[...pendingAssignments()].sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,3);$("#assignment-count").textContent=`${pendingAssignments().length} pendientes`;$("#home-deliveries").innerHTML=items.map(item=>{const course=assignmentCourse(item),state=assignmentStatus(item);return`<button class="home-delivery-card ${state.priorityTone}" data-assignment="${item.id}"><span>📝</span><div><small>${state.due}</small><b>${item.title}</b><p>${course?.name||"Ramo"}</p></div><i>›</i></button>`}).join("")||"<p class='card-meta'>No tienes entregas pendientes.</p>"}
function renderEvaluations(){const items=[...evaluations].sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)),pending=items.filter(item=>item.status!=="completed"&&daysUntil(item.date)>=0).length;$("#evaluation-count").textContent=`${pending} próximas`;$("#evaluations-list").innerHTML=items.map(item=>{const course=evaluationCourse(item),state=evaluationStatus(item);return`<article class="evaluation-card ${state.tone}"><div class="evaluation-card-top"><span class="evaluation-marker">${state.tone==="late"?"🔴":state.tone==="request"?"🟡":"🟢"}</span><div><span class="eyebrow">${state.label}</span><h3>${course?.name||"Ramo"}</h3></div><span class="badge ${state.tone}">${state.label}</span></div><h4>${item.title}</h4><div class="evaluation-meta"><span>📅 ${formatDate(item.date)}</span><span>⏰ ${item.time}</span><span>📍 ${item.room}</span></div><div class="card-actions"><small>Ponderación: <b>${item.percentage}%</b></small><button class="outline-btn" data-evaluation="${item.id}">Ver detalle</button></div></article>`}).join("")}
function evaluationDetail(id){const item=evaluations.find(evaluation=>evaluation.id===id),course=evaluationCourse(item||{});if(!item||!course)return;const state=evaluationStatus(item);$("#evaluation-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">EVALUACIÓN ACADÉMICA</span><h2>${item.title}</h2><p>${course.name} · ${course.teacher}</p><span class="badge ${state.tone}">${state.label}</span></div><section class="class-info-card"><div><span>Fecha</span><b>${formatDate(item.date)}</b></div><div><span>Hora</span><b>${item.time}</b></div><div><span>Sala</span><b>${item.room}</b></div><div><span>Ponderación</span><b>${item.percentage}%</b></div><div><span>Estado</span><b class="${state.tone==="late"?"risk-text":"success-text"}">${state.label}</b></div></section><div class="evaluation-actions"><button class="primary-btn" data-evaluation-course="${course.id}">Ver ramo</button><button class="outline-btn" data-evaluation-virtual="${course.id}">Ver aula virtual</button><button class="outline-btn" data-evaluation-reminder="${item.id}">Agregar recordatorio</button></div>`;showScreen("evaluation-detail")}
function addEvaluationReminder(id){const item=evaluations.find(evaluation=>evaluation.id===id),course=evaluationCourse(item||{});if(!item||!course)return;const list=reminders(),exists=list.some(reminder=>reminder.evaluationId===id);if(!exists){list.push({evaluationId:id,title:`${item.title} · ${course.name}`,date:item.date,type:"Evaluación",when:"1 día antes"});localStorage.setItem("uboReminders",JSON.stringify(list))}toast(exists?"Este recordatorio ya está agregado.":"Recordatorio agregado al calendario académico.")}
function renderWeeklySchedule(){const days=["lunes","martes","miércoles","jueves","viernes"],labels={lunes:"Lunes",martes:"Martes",miércoles:"Miércoles",jueves:"Jueves",viernes:"Viernes"};$("#weekly-schedule-content").innerHTML=days.map(day=>{const meetings=schedule.filter(item=>item.day===day);return`<section class="schedule-day"><div class="schedule-day-title"><h3>${labels[day]}</h3><span>${meetings.length} ${meetings.length===1?"clase":"clases"}</span></div>${meetings.length?meetings.map(item=>`<article class="weekly-class-card"><time>${item.time}</time><div class="weekly-class-main"><span class="today-subject-icon">${item.subjectId==="iot"?"💻":"📘"}</span><h4>${item.subject}</h4><p><b>Sala:</b> ${item.room}</p><p><b>Profesor:</b> ${item.professor}</p></div><button class="outline-btn" data-class="${item.subjectId}" data-class-day="${item.day}">Ver detalle</button></article>`).join(""):`<p class="schedule-empty">No tienes clases programadas.</p>`}</section>`}).join("")}
function classDetail(subjectId,day){const course=courses.find(item=>item.id===subjectId),meeting=schedule.find(item=>item.subjectId===subjectId&&item.day===day)||schedule.find(item=>item.subjectId===subjectId&&item.day===todayKey())||schedule.find(item=>item.subjectId===subjectId),location=campusLocationFor(meeting?.room);if(!course||!meeting)return;$("#class-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">CLASE PROGRAMADA</span><h2>${course.name}</h2><p>${meeting.professor}</p></div><section class="class-info-card"><div><span>Horario</span><b>${meeting.time}</b></div><div><span>Sala</span><b>${meeting.room}</b></div><div><span>Asistencia</span><b class="${course.attendance<80?"risk-text":"success-text"}">${course.attendance}% · ${course.attendance<80?"Atención requerida":"Al día"}</b></div></section><section class="card-section"><h3>Seguimiento académico</h3><div class="summary-row"><div><b>Próxima evaluación</b><p>${course.next}</p></div><span class="badge request">Pendiente</span></div><div class="summary-row"><div><b>Última nota</b><p>${course.last}</p></div><span class="badge available">${course.grade.toFixed(1)}</span></div></section><div class="class-actions"><button class="primary-btn" data-class-virtual="${course.id}">Entrar al aula virtual</button><button class="outline-btn" data-go="attendance" data-attendance-course="${course.id}">Ver asistencia</button>${location?`<button class="outline-btn" data-campus-location="${location.id}">Ver ubicación</button>`:""}</div>`;showScreen("class-detail")}
function classVirtual(subjectId){const course=courses.find(item=>item.id===subjectId),tasks=assignments.filter(item=>item.subjectId===course?.id&&item.status!=="completed");if(!course)return;$("#virtual-classroom-content").innerHTML=`<div class="detail-title"><span class="eyebrow">AULA VIRTUAL · DEMO</span><h2>${course.name}</h2><p>${course.teacher}</p></div><section class="card-section"><h3>Anuncios del profesor</h3><article class="announcement-card"><b>Material disponible</b><p>Ya puedes revisar los recursos de la unidad y las instrucciones de la próxima evaluación.</p></article></section><section class="card-section"><h3>Materiales</h3>${["Presentación unidad actual","Guía de ejercicios","Lectura complementaria"].map(item=>`<div class="material-row"><span class="icon-badge blue">▤</span><div><b>${item}</b><p>Recurso demo del aula virtual.</p></div><button class="small-action" data-toast="Material abierto en modo demo.">Abrir</button></div>`).join("")}</section><section class="card-section"><h3>Trabajos</h3>${tasks.map(item=>{const state=assignmentStatus(item);return`<div class="task-row"><span class="badge ${state.priorityTone}">${state.priority}</span><div><b>${item.title}</b><p>${state.due} · ${item.dueTime}</p></div></div>`}).join("")||"<p class='card-meta'>No hay trabajos pendientes.</p>"}</section>`;showScreen("virtual-classroom")}
function renderCourses(){$("#course-list").innerHTML=courses.map(c=>`<article class="course-card course-summary-card"><div class="card-top"><div><h3>${c.name}</h3><p class="card-meta">${c.teacher}</p></div><span class="badge ${tone(c.state)}">${c.state}</span></div><div class="course-metrics"><span><b>Promedio</b>${c.grade.toFixed(1)}</span><span><b>Asistencia</b>${c.attendance}%</span></div><div class="course-timeline"><p><b>Próxima:</b> ${c.next}</p><p><b>Última:</b> ${c.last}</p></div><div class="card-actions"><small>Actualizado: ${c.updated}</small><button class="outline-btn" data-course="${c.id}">Ver detalle</button></div></article>`).join("")}
function courseDetail(id){const c=courses.find(x=>x.id===id);if(!c)return;const tasks=assignments.filter(item=>item.subjectId===c.id&&item.status!=="completed");$("#course-detail-content").innerHTML=`<div class="detail-title"><h2>${c.name}</h2><p>${c.teacher} · Semestre 2026-1</p><span class="badge ${tone(c.state)}">${c.state}</span></div><div class="course-detail-grid"><article class="summary-row"><div><b>Promedio</b><p>${c.last}</p></div><strong>${c.grade.toFixed(1)}</strong></article><article class="summary-row"><div><b>Asistencia</b><p>${c.attendance>=80?"Cumple requisito":"Atención requerida"}</p></div><strong>${c.attendance}%</strong></article></div><section class="card-section"><h3>Próxima evaluación</h3><div class="task-row"><span class="icon-badge blue">◷</span><div><b>${c.next}</b><p>Revisa instrucciones en el aula virtual.</p></div></div></section><section class="card-section"><h3>Trabajos del ramo</h3>${tasks.map(item=>{const state=assignmentStatus(item);return`<div class="task-row"><span class="badge ${state.priorityTone}">${state.priority}</span><div><b>${item.title}</b><p>${state.due} · ${item.dueTime}</p></div></div>`}).join("")||"<p class='card-meta'>No tienes trabajos pendientes.</p>"}</section><button class="primary-btn" data-class-virtual="${c.id}">Ir al aula virtual</button>`;showScreen("course-detail")}
function renderAttendance(){$("#attendance-list").innerHTML=courses.map(c=>`<article class="course-card"><h3>${c.name}</h3><p class="card-meta">${c.attendance}% de asistencia registrada</p><div class="card-actions"><span class="badge ${c.attendance<80?"late":"available"}">${c.attendance<80?"Atención requerida":"Cumple requisito"}</span><button class="outline-btn" data-go="attendance-calculator" data-attendance-course="${c.id}">Calcular</button></div></article>`).join("");$("#attendance-course").innerHTML=courses.map(c=>`<option value="${c.id}">${c.name}</option>`).join("")}
function calculateAttendance(){const a=Number($("#classes-attended").value),h=Number($("#classes-held").value),f=Number($("#future-classes").value),result=$("#attendance-result");if(!Number.isFinite(a)||!Number.isFinite(h)||!Number.isFinite(f)||h<=0||a<0||a>h||f<0)result.textContent="Verifica las clases realizadas, asistidas y futuras.";else{const p=((a+f)/(h+f)*100).toFixed(1);result.textContent=`Tu asistencia proyectada es ${p}%. ${Number(p)>=75?"Cumples el mínimo de asistencia.":"Debes mejorar tu asistencia para alcanzar el mínimo de 75%."}`}result.classList.remove("hidden")}
function renderAssignments(filter=assignmentFilter){assignmentFilter=filter;const items=assignments.filter(item=>filter==="Todas"||filter==="Pendientes"&&item.status==="pending"||filter==="Entregadas"&&item.status==="completed"||filter==="Atrasadas"&&(item.status==="overdue"||daysUntil(item.dueDate)<0));$("#assignment-filters").innerHTML=["Todas","Pendientes","Entregadas","Atrasadas"].map(value=>`<button class="filter-btn ${value===filter?"active":""}" data-filter="${value}">${value}</button>`).join("");$("#assignment-list").innerHTML=items.map(item=>{const course=assignmentCourse(item),state=assignmentStatus(item);return`<article class="assignment-card delivery-card ${state.tone}"><div class="card-top"><div><span class="eyebrow">${state.priority} prioridad</span><h3>${item.title}</h3><p>${course?.name||"Ramo"}</p></div><span class="badge ${state.tone}">${state.label}</span></div><div class="assignment-meta"><span class="badge ${state.priorityTone}">Prioridad ${state.priority}</span><span class="due-label ${state.tone}">◷ ${state.due} · ${item.dueTime}</span></div><div class="card-actions"><button class="small-action" data-assignment-virtual="${item.subjectId}">Aula virtual</button><button class="outline-btn" data-assignment="${item.id}">Ver detalle</button></div></article>`}).join("")||"<p class='card-meta'>No hay entregas en esta categoría.</p>"}
function assignmentDetail(id){const item=assignments.find(assignment=>assignment.id===id),course=assignmentCourse(item||{});if(!item||!course)return;const state=assignmentStatus(item),hasReminder=reminders().some(reminder=>reminder.assignmentId===id);$("#assignment-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">ENTREGA ACADÉMICA</span><h2>${item.title}</h2><p>${course.name} · ${course.teacher}</p><span class="badge ${state.tone}">${state.label}</span></div><section class="class-info-card"><div><span>Fecha límite</span><b>${formatDate(item.dueDate)}</b></div><div><span>Hora</span><b>${item.dueTime}</b></div><div><span>Prioridad</span><b class="${state.priorityTone==="late"?"risk-text":""}">${state.priority}</b></div><div><span>Estado</span><b class="${state.tone==="late"?"risk-text":"success-text"}">${state.label}</b></div><div><span>Recordatorio</span><b class="${hasReminder?"success-text":""}">${hasReminder?"Configurado":"Sin configurar"}</b></div></section><section class="card-section"><h3>Descripción</h3><article class="announcement-card"><p>${item.description}</p></article></section><div class="assignment-actions"><button class="primary-btn" data-assignment-virtual="${course.id}">Abrir aula virtual</button><button class="outline-btn" data-assignment-course="${course.id}">Ver ramo</button><button class="outline-btn" data-assignment-reminder="${item.id}">Agregar recordatorio</button></div>`;showScreen("assignment-detail")}
function renderAlerts(){const items=[["Entrega próxima","El informe práctico de Programación IoT vence hoy.","request"],["Asistencia de Álgebra","Tu asistencia es de 76%. Procura llegar al mínimo requerido.","late"],["Nueva calificación","Se publicó una nota en Habilidades Académicas.","available"]],html=items.map(a=>`<article class="alert-card"><span class="badge ${a[2]}">${a[0]}</span><p class="card-meta">${a[1]}</p><button class="text-btn" data-toast="Alerta marcada como leída.">Marcar leída</button></article>`).join("");$("#alerts-list").innerHTML=html;$("#home-alerts").innerHTML=html}
function renderCertificates(){$("#certificate-list").innerHTML=certificates.map(c=>`<article class="certificate-card"><div class="card-top"><div><h3>${c[0]}</h3><p>${c[1]}</p></div><span class="badge ${tone(c[2])}">${c[2]}</span></div><div class="card-actions"><small>Registro Académico UBO</small><button class="outline-btn" data-toast="${c[2]==="Disponible"?"Certificado generado correctamente en modo demo.":"Solicitud enviada correctamente en modo demo."}">${c[2]==="Disponible"?"Descargar":"Solicitar"}</button></div></article>`).join("")}
function documentRequests(){const list=json("uboDocumentRequests",[]);return Array.isArray(list)?list:[]}
function documentRequest(id){return documentRequests().find(item=>item.documentId===id)}
function documentStatus(doc){const request=documentRequest(doc.id),key=request?.status==="Generado"?"generated":request?.status==="En revisión"?"review":doc.status||"available",meta={available:{label:"Disponible",tone:"available",icon:"🟢"},review:{label:"En revisión",tone:"request",icon:"🟡"},generated:{label:"Generado",tone:"generated",icon:"🔵"}}[key];return{key,...meta,date:request?.date||doc.issueDate||null,code:request?.code||`UBO-${new Date().getFullYear()}-${doc.identifier}`,identifier:doc.identifier}}
function renderDocuments(){const available=documents.filter(doc=>documentStatus(doc).key==="available").length;$("#document-count").textContent=`${available} disponibles`;$("#documents-list").innerHTML=documents.map(doc=>{const state=documentStatus(doc),action=state.key==="available"?"Solicitar documento":state.key==="review"?"Consultar estado":"Visualizar";return`<article class="document-card document-card-${state.key}"><div class="document-icon">📄</div><div class="document-card-main"><div class="card-top"><div><span class="eyebrow">${doc.category==="academic"?"ACADÉMICO":doc.category==="administrative"?"ADMINISTRATIVO":"CERTIFICADO"}</span><h3>${doc.title}</h3></div><span class="badge document-status ${state.key}">${state.icon} ${state.label}</span></div><p>${doc.description}</p><div class="card-actions"><small>ID demo: ${state.identifier}</small><button class="outline-btn" data-document="${doc.id}">${action}</button></div></div></article>`}).join("");const requests=documentRequests();$("#document-requests").innerHTML=requests.map(item=>`<article class="document-request-row"><div><b>${item.title}</b><p>${formatDate(item.date)} · ${item.code}</p></div><span class="badge document-status ${item.status==="Generado"?"generated":"review"}">${item.status}</span></article>`).join("")||"<p class='card-meta'>Aún no tienes solicitudes de documentos.</p>"}
function documentDetail(id){const doc=documents.find(item=>item.id===id);if(!doc)return;const s=student(),state=documentStatus(doc),emission=state.date?formatDate(state.date):"Pendiente de emisión",actions=state.key==="available"?`<button class="primary-btn" data-document-request="${doc.id}">Solicitar documento</button>`:state.key==="review"?`<button class="primary-btn" data-document-review="${doc.id}">Consultar estado</button>`:`<button class="primary-btn" data-document-preview="${doc.id}">Visualizar documento</button><button class="outline-btn" data-document-download="${doc.id}">Descargar PDF</button>`;$("#document-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">📄 REGISTRO ACADÉMICO UBO</span><h2>${doc.title}</h2><p>${doc.description}</p><span class="badge document-status ${state.key}">${state.icon} ${state.label}</span></div><section class="document-institutional-data"><div><span>Código de documento</span><b>${state.code}</b></div><div><span>Identificador demo</span><b>${state.identifier}</b></div><div><span>Fecha de emisión</span><b>${emission}</b></div><div><span>Unidad emisora</span><b>Registro Académico UBO</b></div></section><section class="class-info-card"><div><span>Estudiante</span><b>${s.name}</b></div><div><span>Carrera</span><b>${s.career}</b></div><div><span>Estado</span><b>${state.label}</b></div><div class="qr-placeholder"><span>QR</span><small>Verificación demo</small></div></section><section class="card-section"><h3>Información institucional</h3><article class="announcement-card"><p>Documento demostrativo para consultas y solicitudes académicas. No tiene validez oficial.</p></article></section><div class="document-detail-actions">${actions}</div>`;showScreen("document-detail")}
function requestDocument(id){const doc=documents.find(item=>item.id===id);if(!doc)return;const list=documentRequests(),existing=list.find(item=>item.documentId===id),record={documentId:id,title:doc.title,status:"En revisión",date:isoDate(),code:`UBO-${new Date().getFullYear()}-DEMO${String(list.length+1).padStart(3,"0")}`};if(existing)Object.assign(existing,record);else list.unshift(record);localStorage.setItem("uboDocumentRequests",JSON.stringify(list));renderDocuments();if(currentScreen==="document-detail")documentDetail(id);toast("Solicitud registrada. Tu documento está en revisión.")}
function checkDocumentStatus(id){const doc=documents.find(item=>item.id===id),list=documentRequests(),request=list.find(item=>item.documentId===id);if(!doc)return;if(request){request.status="Generado";request.date=isoDate();localStorage.setItem("uboDocumentRequests",JSON.stringify(list));renderDocuments();if(currentScreen==="document-detail")documentDetail(id);toast("Tu documento ya está generado en modo demo.");return}toast("La solicitud sigue en revisión.")}
function documentPreview(id){const doc=documents.find(item=>item.id===id);if(!doc)return;const s=student(),state=documentStatus(doc);if(state.key!=="generated"){toast("El documento estará disponible cuando finalice la revisión.");return}$("#document-preview-content").innerHTML=`<article class="institutional-document official"><header><div class="document-logo">UBO</div><div><span>UNIVERSIDAD BERNARDO O'HIGGINS</span><b>Vicerrectoría Académica · Registro Académico</b></div><span class="document-copy">COPIA DIGITAL</span></header><div class="document-rule"></div><h2>${doc.title.toUpperCase()}</h2><p class="document-intro">La Universidad Bernardo O'Higgins, a través de su Registro Académico, certifica que:</p><h3>${s.name}</h3><p class="document-student-data">RUT: ${s.rut}<br>Carrera: ${s.career}<br>Período académico: ${s.semester}</p><p>se encuentra registrado/a en calidad de <b>${s.status.toLowerCase()}</b>. Este certificado se emite para fines de demostración académica dentro de Ubo Academic Hub.</p><div class="document-data"><div><span>Fecha de emisión</span><b>${formatDate(state.date)} de ${new Date().getFullYear()}</b></div><div><span>Código de documento</span><b>${state.code}</b></div><div><span>Identificador demo</span><b>${state.identifier}</b></div></div><div class="document-validation"><div class="qr-placeholder large"><span>QR</span><small>Validación demo</small></div><div class="document-seal"><b>UBO</b><span>SELLO DIGITAL<br>DEMO</span></div><div class="document-signature"><i></i><b>Registro Académico</b><span>Universidad Bernardo O'Higgins</span></div></div><footer>Documento demostrativo generado por Ubo Academic Hub. Sin validez oficial.</footer></article><div class="document-preview-actions"><button class="primary-btn" data-document-download="${doc.id}">Descargar PDF</button><button class="outline-btn" data-document-back>Volver al detalle</button></div>`;showScreen("document-preview")}
function downloadDocument(id){const doc=documents.find(item=>item.id===id);if(!doc)return;toast(`Descarga simulada: ${doc.title}.pdf`)}
function renderCampusEvents(filter="Todos"){const filters=["Todos","Charlas","DAE","Deportes","Cultura","Académicos"],map={Charlas:"Charla",Académicos:"Académico"},items=campusEvents.filter(item=>filter==="Todos"||item.category===(map[filter]||filter));$("#campus-event-count").textContent=`${campusEvents.length} eventos`;$("#campus-filters").innerHTML=filters.map(item=>`<button class="filter-btn ${item===filter?"active":""}" data-campus-filter="${item}">${item}</button>`).join("");$("#campus-events-list").innerHTML=items.map(item=>{const meta=campusMeta(item.category),registered=campusRegistered(item.id);return`<article class="campus-event-card ${meta.tone}"><div class="campus-event-icon">${meta.icon}</div><div class="campus-event-main"><div class="card-top"><div><span class="eyebrow">${item.category}</span><h3>${item.title}</h3></div><span class="badge ${registered?"available":"request"}">${registered?"Inscrito":"No inscrito"}</span></div><div class="campus-event-meta"><span>📅 ${formatDate(item.date)}</span><span>⏰ ${item.time}</span><span>📍 ${item.location}</span></div><div class="card-actions"><small>${registered?"Tu cupo está reservado.":"Inscripción disponible en modo demo."}</small><button class="outline-btn" data-campus-event="${item.id}">Ver detalle</button></div></div></article>`}).join("")||"<p class='card-meta'>No hay eventos en esta categoría.</p>";const registered=campusEvents.filter(item=>campusRegistered(item.id));$("#my-campus-events").innerHTML=registered.map(item=>`<button class="my-campus-event" data-campus-event="${item.id}"><span>🎓</span><div><b>${item.title}</b><p>Inscrito · ${formatDate(item.date)}</p></div><i>›</i></button>`).join("")||"<p class='card-meta'>Todavía no te inscribes a eventos.</p>"}
function campusEventDetail(id){const item=campusEvents.find(event=>event.id===id),location=campusLocationFor(item?.location);if(!item)return;const meta=campusMeta(item.category),registered=campusRegistered(id),inCalendar=campusOnCalendar(id),hasReminder=reminders().some(reminder=>reminder.campusEventId===id);$("#campus-event-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">${meta.icon} VIDA UBO · ${item.category.toUpperCase()}</span><h2>${item.title}</h2><p>${item.description}</p><span class="badge ${registered?"available":"request"}">${registered?"Inscrito":"No inscrito"}</span></div><section class="class-info-card"><div><span>Fecha</span><b>${formatDate(item.date)}</b></div><div><span>Hora</span><b>${item.time}</b></div><div><span>Lugar</span><b>${item.location}</b></div><div><span>Categoría</span><b>${item.category}</b></div></section><section class="card-section"><h3>Información del evento</h3><article class="announcement-card"><p>Actividad demostrativa de Vida UBO. La inscripción no reserva cupos reales.</p></article></section><div class="campus-event-actions"><button class="primary-btn" data-campus-register="${item.id}">${registered?"Inscrito ✓":"Inscribirme"}</button><button class="outline-btn" data-campus-reminder="${item.id}">${hasReminder?"Recordatorio agregado":"Agregar recordatorio"}</button><button class="outline-btn" data-campus-calendar="${item.id}">${inCalendar?"Agregado al calendario":"Agregar al calendario"}</button>${location?`<button class="outline-btn" data-campus-location="${location.id}">Ver ubicación</button>`:""}</div>`;showScreen("campus-event-detail")}
function registerCampusEvent(id){const item=campusEvents.find(event=>event.id===id),list=campusRegistrations();if(!item)return;if(!campusRegistered(id)){list.push({eventId:id,date:isoDate()});localStorage.setItem("uboCampusRegistrations",JSON.stringify(list))}const calendar=campusCalendarIds();if(!calendar.includes(id)){calendar.push(id);localStorage.setItem("uboCampusCalendar",JSON.stringify(calendar))}renderCampusEvents();renderHomeEvents();renderHomeNotifications();if(currentScreen==="campus-event-detail")campusEventDetail(id);toast("Inscripción registrada y evento agregado al calendario.")}
function addCampusCalendar(id){const item=campusEvents.find(event=>event.id===id),list=campusCalendarIds();if(!item)return;if(!list.includes(id)){list.push(id);localStorage.setItem("uboCampusCalendar",JSON.stringify(list));toast("Evento agregado al calendario académico.")}else toast("Este evento ya está en tu calendario.");renderCampusEvents();renderHomeEvents();if(currentScreen==="campus-event-detail")campusEventDetail(id)}
function addCampusReminder(id){const item=campusEvents.find(event=>event.id===id),list=reminders();if(!item)return;const exists=list.some(reminder=>reminder.campusEventId===id);if(!exists){list.push({campusEventId:id,title:item.title,date:item.date,time:item.time,room:item.location,type:"Evento UBO",when:"1 día antes",subject:"Vida UBO"});localStorage.setItem("uboReminders",JSON.stringify(list));toast("Recordatorio agregado al calendario académico.")}else toast("Este recordatorio ya está agregado.");if(currentScreen==="campus-event-detail")campusEventDetail(id)}
function libraryStatus(book){return({available:{label:"Disponible",tone:"available",icon:"🟢"},borrowed:{label:"Prestado",tone:"request",icon:"🟡"},reserved:{label:"Reservado",tone:"late",icon:"🔵"}}[book.status]||{label:"Disponible",tone:"available",icon:"🟢"})}
function libraryCover(book){return `<div class="book-cover ${book.category.toLowerCase().includes("seguridad")?"security":"informatics"}"><span>UBO</span><b>${book.title.split(" ").slice(0,2).join(" ")}</b><small>${book.category}</small></div>`}
function renderLibrary(filter=libraryFilter,search=librarySearch){libraryFilter=filter;librarySearch=search;$("#library-search").value=search;const query=search.trim().toLowerCase(),books=activeLibraryBooks().filter(book=>(filter==="Todos"||filter==="Disponibles"&&book.status==="available"||filter==="Prestados"&&book.status==="borrowed"||filter==="Reservados"&&book.status==="reserved")&&(!query||[book.title,book.author,book.category].some(value=>value.toLowerCase().includes(query))));$("#library-resource-count").textContent=`${libraryBooks.length} recursos`;$("#library-filters").innerHTML=["Todos","Disponibles","Prestados","Reservados"].map(item=>`<button class="filter-btn ${item===filter?"active":""}" data-library-filter="${item}">${item}</button>`).join("");$("#library-books-list").innerHTML=books.map(book=>{const state=libraryStatus(book);return`<article class="library-book-card"><div>${libraryCover(book)}</div><div class="library-book-main"><div class="card-top"><div><span class="eyebrow">${book.category}</span><h3>${book.title}</h3></div><span class="badge ${state.tone}">${state.icon} ${state.label}</span></div><p>Autor: ${book.author}</p><div class="card-actions"><small>${book.status==="borrowed"?`Devolución: ${formatDate(book.returnDate)}`:book.status==="reserved"?"Reserva activa":"Disponible para reserva"}</small><button class="outline-btn" data-library-book="${book.id}">Ver detalle</button></div></div></article>`}).join("")||"<p class='card-meta'>No encontramos recursos con esos criterios.</p>";const loans=activeLibraryBooks().filter(book=>book.status==="borrowed");$("#library-loans").innerHTML=loans.map(book=>`<button class="library-loan-row" data-library-book="${book.id}"><span>📚</span><div><b>${book.title}</b><p>Devolver: ${formatDate(book.returnDate)} · Prestado</p></div><i>›</i></button>`).join("")||"<p class='card-meta'>No tienes préstamos activos.</p>"}
function libraryBookDetail(id){const book=libraryBook(id);if(!book)return;const state=libraryStatus(book),hasReminder=reminders().some(reminder=>reminder.libraryBookId===id),actions=book.status==="available"?`<button class="primary-btn" data-library-reserve="${id}">Reservar</button>`:book.status==="reserved"?`<button class="primary-btn" data-library-reserve="${id}">Reserva confirmada</button>`:"";$("#library-book-detail-content").innerHTML=`<section class="library-detail-hero">${libraryCover(book)}<div><span class="eyebrow">BIBLIOTECA UBO · ${book.category.toUpperCase()}</span><h2>${book.title}</h2><p>${book.author}</p><span class="badge ${state.tone}">${state.icon} ${state.label}</span></div></section><section class="class-info-card"><div><span>Autor</span><b>${book.author}</b></div><div><span>Categoría</span><b>${book.category}</b></div><div><span>Fecha préstamo</span><b>${book.loanDate?formatDate(book.loanDate):"Sin préstamo activo"}</b></div><div><span>Fecha devolución</span><b>${book.returnDate?formatDate(book.returnDate):"Por confirmar"}</b></div></section><section class="card-section"><h3>Disponibilidad institucional</h3><article class="announcement-card"><p>Recurso bibliográfico demo de Biblioteca UBO. Consulta la disponibilidad presencial antes de retirar material.</p></article></section><div class="library-book-actions">${actions}<button class="outline-btn" data-library-reminder="${id}" ${book.returnDate?"":"disabled"}>${hasReminder?"Recordatorio agregado":"Agregar recordatorio"}</button><button class="outline-btn" data-toast="Recursos relacionados disponibles próximamente.">Ver recursos relacionados</button></div>`;showScreen("library-book-detail")}
