function calendarEventDetail(key){const item=calendarEntries().find(entry=>entry.key===key),course=evaluationCourse(item||{});if(!item)return;const meta=eventMeta(item.type),hasReminder=item.source==="reminder"||reminders().some(reminder=>reminder.evaluationId===item.id||reminder.assignmentId===item.id);$("#calendar-event-detail-content").innerHTML=`<div class="detail-title"><span class="eyebrow">${meta.icon} ${item.type.toUpperCase()}</span><h2>${item.title}</h2><p>${course?.name||item.subject||"Actividad institucional"}</p><span class="badge ${meta.tone}">${relativeEvent(item)}</span></div><section class="class-info-card"><div><span>Tipo</span><b>${item.type}${item.eventType?` · ${item.eventType}`:""}</b></div><div><span>Fecha</span><b>${formatDate(item.date)}</b></div><div><span>Hora</span><b>${item.time||"Por confirmar"}</b></div><div><span>Sala</span><b>${item.room||"Por confirmar"}</b></div><div><span>Recordatorio</span><b class="${hasReminder?"success-text":""}">${hasReminder?"Configurado":"Sin configurar"}</b></div></section><section class="card-section"><h3>Descripción</h3><article class="announcement-card"><p>${item.description||"Sin descripción adicional."}</p></article></section>${course?`<div class="event-detail-actions"><button class="primary-btn" data-calendar-course="${course.id}">Ver ramo</button><button class="outline-btn" data-calendar-virtual="${course.id}">Ver aula virtual</button></div>`:""}`;showScreen("calendar-event-detail")}
function renderDae(){const s=student(),history=json("uboDaeRequests",[]);$("#dae-name").value=s.name;$("#dae-email").value=s.email;$("#dae-history").innerHTML=history.map(x=>`<article class="summary-row"><div><b>${escapeHTML(x.subject)}</b><p>${escapeHTML(x.type)} · ${escapeHTML(x.date)}</p></div><span class="badge request">Enviada</span></article>`).join("")||"<p class='card-meta'>Aún no envías solicitudes.</p>"}
function submitDae(form){const subject=$("#dae-subject").value.trim(),message=$("#dae-message").value.trim();if(!subject||!message){toast("Completa asunto y mensaje.");return}const history=json("uboDaeRequests",[]);history.unshift({subject,type:$("#dae-type").value,date:new Date().toLocaleDateString("es-CL")});localStorage.setItem("uboDaeRequests",JSON.stringify(history));form.reset();renderDae();toast("Solicitud enviada a DAE en modo demo.")}
function saveReminder(form){const title=$("#reminder-title").value.trim(),date=$("#reminder-date").value;if(!title||!date){toast("Completa título y fecha del recordatorio.");return}const list=reminders();list.push({title,date,type:$("#reminder-type").value,when:$("#reminder-when").value});localStorage.setItem("uboReminders",JSON.stringify(list));form.reset();renderCalendar(Number(date.slice(-2)));toast("Recordatorio guardado correctamente.")}
function renderScreen(id){({home:()=>{renderProfile();renderDashboard();renderToday();renderHomeAttention();renderHomeNotifications();renderHomeEvents();renderHomeDeliveries();renderEvaluations();renderDocuments();renderCampusEvents();renderLibrary();renderCampusMap();renderHelpCenter()},"weekly-schedule":renderWeeklySchedule,evaluations:renderEvaluations,courses:renderCourses,attendance:renderAttendance,assignments:()=>renderAssignments(),notifications:()=>renderNotifications(),documents:renderDocuments,"campus-events":renderCampusEvents,library:()=>renderLibrary(),"campus-map":()=>renderCampusMap(),"help-center":()=>renderHelpCenter(),alerts:renderAlerts,certificates:renderCertificates,virtual:renderVirtual,summary:renderSummary,profile:renderProfile,"personal-data":renderPersonal,"student-card":renderStudentCard,"student-benefits":renderBenefits,"institutional-mail":renderMail,"mail-detail":renderMailDetail,"dae-contact":renderDae,"academic-calendar":renderCalendar}[id])?.()}
function prepareLogin(){const remember=$("#remember-username"),legacy=localStorage.getItem("uboRememberedUsername"),remembered=localStorage.getItem("uboRememberedUser")||legacy||"";if(!localStorage.getItem("uboRememberedUser")&&legacy)localStorage.setItem("uboRememberedUser",legacy);localStorage.removeItem("uboRememberedUsername");localStorage.removeItem("uboRememberUsername");$("#loginUsername").value=remembered;$("#loginPassword").value="";$("#loginPassword").type="password";remember.checked=Boolean(remembered);$("#login-error").classList.remove("show")}
function login(){const username=$("#loginUsername").value.trim().toLowerCase(),password=$("#loginPassword").value,error=$("#login-error"),user=userFor(username);if(!username||!password||!user||user.password!==password){error.textContent=!username?"Ingresa tu usuario institucional para continuar.":!password?"Ingresa tu contraseña para continuar.":!user?"No encontramos ese usuario. Revisa cómo lo escribiste o usa Ayuda UBO.":"La contraseña no coincide. Revísala o solicita una recuperación demo.";error.classList.add("show");return}if($("#remember-username").checked)localStorage.setItem("uboRememberedUser",username);else localStorage.removeItem("uboRememberedUser");saveStudent({...user.student},user.username);error.classList.remove("show");renderProfile();showScreen("home",{resetHistory:true});toast("Sesión iniciada correctamente en modo demo.")}
function submitPasswordRecovery(form){const username=$("#recovery-username").value.trim().toLowerCase(),email=$("#recovery-email").value.trim().toLowerCase(),error=$("#recovery-error"),result=$("#password-recovery-result");if(!username||!email.endsWith("@pregrado.ubo.cl")){error.textContent=!username?"Ingresa tu usuario institucional.":"Ingresa un correo institucional válido (@pregrado.ubo.cl).";error.classList.add("show");result.classList.add("hidden");return}error.classList.remove("show");result.textContent="Solicitud enviada. Recibirás instrucciones de recuperación en modo demo.";result.classList.remove("hidden");form.reset()}
function submitPublicSupport(form){const message=$("#public-support-message").value.trim();if(!message){toast("Describe tu problema para enviar la consulta.");return}const requests=json("uboPublicSupport",[]);requests.unshift({message,date:new Date().toLocaleString("es-CL")});localStorage.setItem("uboPublicSupport",JSON.stringify(requests));form.reset();toast("Consulta enviada a soporte en modo demo.")}
function logout(){localStorage.removeItem("uboSession");navigationStack=[];prepareLogin();showScreen("login");toast("Sesión cerrada correctamente.")}
function setupEvents(){document.addEventListener("click",event=>{const nav=event.target.closest("[data-go]");if(nav){if(nav.dataset.go==="institutional-mail"&&currentScreen==="mail-detail"){goBack();return}const bottom=Boolean(nav.closest(".bottom-nav")),attendanceCourse=nav.dataset.attendanceCourse;showScreen(nav.dataset.go,{resetHistory:bottom});const attendanceSelect=$("#attendance-course");if(attendanceCourse&&attendanceSelect)attendanceSelect.value=attendanceCourse;return}const calendarEvent=event.target.closest("[data-calendar-event]");if(calendarEvent)return calendarEventDetail(calendarEvent.dataset.calendarEvent);const calendarCourseButton=event.target.closest("[data-calendar-course]");if(calendarCourseButton)return courseDetail(calendarCourseButton.dataset.calendarCourse);const calendarVirtualButton=event.target.closest("[data-calendar-virtual]");if(calendarVirtualButton)return classVirtual(calendarVirtualButton.dataset.calendarVirtual);const evaluation=event.target.closest("[data-evaluation]");if(evaluation)return evaluationDetail(evaluation.dataset.evaluation);const evaluationCourseButton=event.target.closest("[data-evaluation-course]");if(evaluationCourseButton)return courseDetail(evaluationCourseButton.dataset.evaluationCourse);const evaluationVirtualButton=event.target.closest("[data-evaluation-virtual]");if(evaluationVirtualButton)return classVirtual(evaluationVirtualButton.dataset.evaluationVirtual);const evaluationReminderButton=event.target.closest("[data-evaluation-reminder]");if(evaluationReminderButton)return addEvaluationReminder(evaluationReminderButton.dataset.evaluationReminder);const classCard=event.target.closest("[data-class]");if(classCard)return classDetail(classCard.dataset.class,classCard.dataset.classDay);const classVirtualButton=event.target.closest("[data-class-virtual]");if(classVirtualButton)return classVirtual(classVirtualButton.dataset.classVirtual);const course=event.target.closest("[data-course]");if(course)return courseDetail(course.dataset.course);const virtual=event.target.closest("[data-virtual]");if(virtual)return virtualDetail(virtual.dataset.virtual);const filter=event.target.closest("[data-filter]");if(filter)return renderAssignments(filter.dataset.filter);const mailF=event.target.closest("[data-mail-filter]");if(mailF){mailFilter=mailF.dataset.mailFilter;return renderMail()}const mail=event.target.closest("[data-mail]");if(mail){selectedMail=Number(mail.dataset.mail);showScreen("mail-detail");return}const toggle=event.target.closest("[data-mail-toggle]");if(toggle){const m=mailData[selectedMail];if(toggle.dataset.mailToggle==="important")m.important=!m.important;else m.unread=true;return renderMailDetail()}const day=event.target.closest("[data-day]");if(day)return renderCalendar(Number(day.dataset.day));if(event.target.closest("[data-benefit]"))return toast(event.target.closest("[data-benefit]").dataset.benefit==="Solicitar"?"Solicitud registrada en modo demo.":"Información disponible próximamente.");const toastButton=event.target.closest("[data-toast]");if(toastButton)toast(toastButton.dataset.toast);if(event.target.closest("#back-btn"))goBack();if(event.target.closest("#logout-btn"))logout();if(event.target.closest("#toggle-password")){const input=$("#loginPassword"),visible=input.type==="text";input.type=visible?"password":"text";event.target.closest("#toggle-password").setAttribute("aria-label",visible?"Mostrar contraseña":"Ocultar contraseña")}if(event.target.closest("#edit-personal")){$$("#personal-form input[name], #personal-form select[name]").forEach(i=>i.disabled=false);$("#edit-personal").classList.add("hidden");$("#personal-edit-actions").classList.remove("hidden")}if(event.target.closest("#cancel-personal"))renderPersonal();const theme=event.target.closest("[data-theme]");if(theme)document.body.classList.toggle("institutional-theme",theme.dataset.theme==="institutional");const size=event.target.closest("[data-text-size]");if(size)document.body.classList.toggle("large-text",size.dataset.textSize==="large")});document.addEventListener("submit",event=>{if(event.target.id==="login-form"){event.preventDefault();login()}if(event.target.id==="password-recovery-form"){event.preventDefault();submitPasswordRecovery(event.target)}if(event.target.id==="public-support-form"){event.preventDefault();submitPublicSupport(event.target)}if(event.target.id==="personal-form"){event.preventDefault();savePersonal(event.target)}if(event.target.id==="dae-form"){event.preventDefault();submitDae(event.target)}if(event.target.id==="reminder-form"){event.preventDefault();saveReminder(event.target)}});$("#calculate-attendance-btn").addEventListener("click",calculateAttendance);$("#simulate-btn").addEventListener("click",()=>{const a=Number($("#current-grade").value),b=Number($("#expected-grade").value),r=$("#grade-result");r.textContent=a<1||a>7||b<1||b>7?"Ingresa notas entre 1.0 y 7.0.":`Tu nota final proyectada es ${(a*.6+b*.4).toFixed(1)}.`;r.classList.remove("hidden")});$("#mail-search").addEventListener("input",renderMail);$("#reduce-motion").addEventListener("change",e=>document.body.classList.toggle("reduce-motion",e.target.checked))}
function init(){renderCourses();renderAttendance();renderAlerts();renderCertificates();renderDocuments();renderCampusEvents();renderLibrary();renderCampusMap();renderHelpCenter();renderVirtual();renderAssignments();renderSummary();renderProfile();renderDashboard();renderHomeAttention();renderHomeNotifications();renderHomeEvents();renderHomeDeliveries();renderOnboarding();prepareLogin();setupEvents();$("#public-help-btn")?.addEventListener("click",event=>{event.stopPropagation();showScreen("public-help")});$("#password-recovery-btn")?.addEventListener("click",event=>{event.stopPropagation();showScreen("password-recovery")});$("#library-search").addEventListener("input",event=>renderLibrary(libraryFilter,event.target.value));$("#campus-location-search").addEventListener("input",event=>renderCampusMap(campusLocationFilter,event.target.value));$("#help-search").addEventListener("input",event=>renderHelpCenter(event.target.value));const activeSession=session();showScreen(activeSession?"home":localStorage.getItem("uboOnboardingCompleted")==="true"?"login":"onboarding",{resetHistory:true});setTimeout(()=>$("#splash")?.classList.add("hide"),900);if("serviceWorker"in navigator&&location.protocol!=="file:")navigator.serviceWorker.register("./service-worker.js").catch(()=>{})}document.addEventListener("DOMContentLoaded",init);
document.addEventListener("click",event=>{const assignment=event.target.closest("[data-assignment]");if(assignment)return assignmentDetail(assignment.dataset.assignment);const courseButton=event.target.closest("[data-assignment-course]");if(courseButton)return courseDetail(courseButton.dataset.assignmentCourse);const virtualButton=event.target.closest("[data-assignment-virtual]");if(virtualButton)return classVirtual(virtualButton.dataset.assignmentVirtual);const reminderButton=event.target.closest("[data-assignment-reminder]");if(reminderButton)return addAssignmentReminder(reminderButton.dataset.assignmentReminder)});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-notification-filter]");if(filter)return renderNotifications(filter.dataset.notificationFilter);const read=event.target.closest("[data-notification-read]");if(read){markNotificationRead(read.dataset.notificationRead);toast("Notificación marcada como leída.");return}const notification=event.target.closest("[data-notification]");if(notification)return notificationDetail(notification.dataset.notification);const evaluation=event.target.closest("[data-notification-evaluation]");if(evaluation)return evaluationDetail(evaluation.dataset.notificationEvaluation);const assignment=event.target.closest("[data-notification-assignment]");if(assignment)return assignmentDetail(assignment.dataset.notificationAssignment);const course=event.target.closest("[data-notification-course]");if(course)return courseDetail(course.dataset.notificationCourse)});
document.addEventListener("click",event=>{if(event.target.closest("[data-document-back]"))return goBack();const documentButton=event.target.closest("[data-document]");if(documentButton)return documentDetail(documentButton.dataset.document);const request=event.target.closest("[data-document-request]");if(request)return requestDocument(request.dataset.documentRequest);const review=event.target.closest("[data-document-review]");if(review)return checkDocumentStatus(review.dataset.documentReview);const preview=event.target.closest("[data-document-preview]");if(preview)return documentPreview(preview.dataset.documentPreview);const download=event.target.closest("[data-document-download]");if(download)return downloadDocument(download.dataset.documentDownload)});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-campus-filter]");if(filter)return renderCampusEvents(filter.dataset.campusFilter);const campus=event.target.closest("[data-campus-event]");if(campus)return campusEventDetail(campus.dataset.campusEvent);const register=event.target.closest("[data-campus-register]");if(register)return registerCampusEvent(register.dataset.campusRegister);const reminder=event.target.closest("[data-campus-reminder]");if(reminder)return addCampusReminder(reminder.dataset.campusReminder);const calendar=event.target.closest("[data-campus-calendar]");if(calendar)return addCampusCalendar(calendar.dataset.campusCalendar);const notificationCampus=event.target.closest("[data-notification-campus]");if(notificationCampus)return campusEventDetail(notificationCampus.dataset.notificationCampus)});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-library-filter]");if(filter)return renderLibrary(filter.dataset.libraryFilter);const book=event.target.closest("[data-library-book]");if(book)return libraryBookDetail(book.dataset.libraryBook);const reserve=event.target.closest("[data-library-reserve]");if(reserve)return reserveLibraryBook(reserve.dataset.libraryReserve);const reminder=event.target.closest("[data-library-reminder]");if(reminder)return addLibraryReminder(reminder.dataset.libraryReminder);const notificationBook=event.target.closest("[data-notification-library]");if(notificationBook)return libraryBookDetail(notificationBook.dataset.notificationLibrary)});
document.addEventListener("click",event=>{const filter=event.target.closest("[data-campus-location-filter]");if(filter)return renderCampusMap(filter.dataset.campusLocationFilter);const location=event.target.closest("[data-campus-location]");if(location)return campusLocationDetail(location.dataset.campusLocation);const nearby=event.target.closest("[data-campus-nearby]");if(nearby)return showCampusNearby(nearby.dataset.campusNearby);const reminder=event.target.closest("[data-campus-location-reminder]");if(reminder)return addCampusLocationReminder(reminder.dataset.campusLocationReminder)});
document.addEventListener("click",event=>{const article=event.target.closest("[data-help]");if(article)return helpDetail(article.dataset.help);const go=event.target.closest("[data-help-go]");if(go)return showScreen(go.dataset.helpGo);const tech=event.target.closest("[data-help-tech]");if(tech)return $("#tech-help-form").classList.toggle("hidden")});
document.addEventListener("submit",event=>{if(event.target.id==="tech-help-form"){event.preventDefault();submitTechnicalHelp(event.target)}});
document.addEventListener("click",event=>{if(event.target.closest("[data-onboarding-next]")){onboardingIndex=Math.min(onboardingIndex+1,onboardingSlides.length-1);return renderOnboarding()}if(event.target.closest("[data-onboarding-prev]")){onboardingIndex=Math.max(onboardingIndex-1,0);return renderOnboarding()}if(event.target.closest("[data-onboarding-skip]")||event.target.closest("[data-onboarding-complete]"))return completeOnboarding()});
document.addEventListener("DOMContentLoaded",()=>{const node=$("#home-date");if(node)node.textContent=new Intl.DateTimeFormat("es-CL",{weekday:"long",day:"numeric",month:"long"}).format(new Date())});
document.addEventListener("click",event=>{const nav=event.target.closest?.("[data-go]"),publicScreens=["login","public-help","password-recovery"];if(nav&&!session()&&!publicScreens.includes(nav.dataset.go)){event.preventDefault();event.stopImmediatePropagation();navigationStack=[];prepareLogin();showScreen("login")}},true);
